s="N _ B A N A _ A _ A N A N A B _ N A N A B A _ A N A".split()
opts={"A":"ANANB","B":"NANAB","C":"ANABN","D":"ANBAN"}
def fill(o):
    it=iter(o); return "".join(next(it) if c=="_" else c for c in s)
def periodic(t,p=6): return all(t[i]==t[i%p] for i in range(len(t)))
fit=[k for k,o in opts.items() if periodic(fill(o))]
assert fit==["D"]
assert fill("ANBAN").startswith("NABANA")

