v=lambda c: ord(c)-64
def sig(p):
    a,b=p.split(" - ")
    return (v(a[1])-v(a[0]), v(b[0])-v(a[0]), v(b[1])-v(b[0]))
opts={"A":"EJ - OT","B":"KP - UZ","C":"PF - OI","D":"CH - MR"}
sigs={k:sig(p) for k,p in opts.items()}
odd=[k for k,s in sigs.items() if s!=(5,10,5)]
assert odd==["C"]

def nxt(t):
    return chr(ord(t[0])-2)+chr(ord(t[1])-2)+str(int(t[2:])-4)
s=["VO39","TM35","RK31","PI27"]
assert all(nxt(a)==b for a,b in zip(s,s[1:]))
ans=nxt("PI27")
opts={"A":"OH24","B":"MG22","C":"NG23","D":"MH24"}
assert ans=="NG23" and [k for k,v in opts.items() if v==ans]==["C"]
